SELECT checkin_date
FROM checkin_record
WHERE user_id = #{userId}
  AND checkin_date >= #{startDate}
  AND checkin_date <= #{endDate}
  AND delete_flag = 0
ORDER BY checkin_date

SELECT id, user_id, checkin_date, create_time, update_time, delete_flag
FROM checkin_record
WHERE user_id = #{userId}
  AND checkin_date = #{checkinDate}
  AND delete_flag = 0
